"""Build both HTML compositions from the measured film manifest."""
import json,shutil
from pathlib import Path
p=Path('examples/the-missing-signature');f=json.loads((p/'film.json').read_text())
style='''
@font-face{font-family:Oswald;src:url('assets/fonts/Oswald.ttf');font-weight:200 700;font-display:block}
@font-face{font-family:'IBM Plex Mono';src:url('assets/fonts/IBMPlexMono-Regular.ttf');font-display:block}
@font-face{font-family:'Signature Caption';src:url('assets/fonts/SignatureCaption.otf');font-display:block}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:#070b14;color:#f1f4f6}#film{position:relative;width:100%;height:100%;overflow:hidden}.clip{position:absolute;inset:0;width:100%;height:100%}#world{position:absolute;inset:0;width:1080px;height:1920px;display:block}#editorial{position:absolute;left:100px;top:250px;width:790px}#eyebrow{display:flex;justify-content:space-between;font:400 22px/30px 'IBM Plex Mono';letter-spacing:2px;color:#99c2cc;border-top:1px solid #426370;padding-top:18px}#headline{font:500 89px/1.08 Oswald;letter-spacing:-.6px;white-space:pre-line;margin:32px 0 0;width:790px;height:222px}#subtitle{font:400 24px/1.5 'IBM Plex Mono';color:#b9d6dc;letter-spacing:.2px;margin-top:22px;width:790px;min-height:72px}#caption{position:absolute;left:100px;top:1330px;width:790px;height:140px;margin:0;background:rgba(7,11,20,.88);padding:5px 10px;font:400 40px/1.35 'IBM Plex Mono';white-space:pre-line;letter-spacing:0;text-shadow:0 2px 6px #000}#attribution{position:absolute;left:100px;top:1260px;width:790px;font:400 20px/30px 'IBM Plex Mono';color:#a3bbc7}#footer{position:absolute;left:100px;top:1620px;width:790px;font:400 20px/1.5 'IBM Plex Mono';letter-spacing:3px;color:#7f9da8;border-bottom:1px solid #2e4756;padding-bottom:18px}.overlay{position:absolute;left:100px;width:790px;display:none;text-align:center}#admin{top:745px}#admin-label{font:400 26px/1.5 'IBM Plex Mono';color:#c0d1d7}#admin-word{font:400 158px/1.35 'IBM Plex Mono';letter-spacing:-8px;border-bottom:2px solid #e0a96b;padding-bottom:14px}#result{top:635px}.digit{font:500 390px/1.15 Oswald;color:#f1f4f6}.small{font:400 25px/1.5 'IBM Plex Mono';color:#a6c8d1}.amber{color:#e0a96b}#scale{top:650px;background:linear-gradient(180deg,rgba(7,11,20,.92),rgba(7,11,20,.6));padding:0 0 22px}.value{font:500 180px/1.12 Oswald;letter-spacing:-4px}.units{font:500 43px/1.2 Oswald;letter-spacing:4px;margin-top:10px}.qualifiers{font:400 27px/1.65 'IBM Plex Mono';color:#f1f4f6;margin-top:20px;white-space:pre-line}.scale-note{font:400 24px/1.3 'IBM Plex Mono';color:#e0a96b;margin-top:8px}#claims{top:1080px;background:#101c29;padding:20px 12px;border:1px solid #456876}.claim-head{font:400 24px/1.6 'IBM Plex Mono';color:#b8d2db}.claim-verdict{font:500 45px/1.2 Oswald;color:#e0a96b;margin-top:12px}#dates{top:800px;text-align:left;background:#0b1420;padding:30px;border-left:3px solid #e0a96b}.date-row{font:400 30px/1.6 'IBM Plex Mono';color:#a7c9d3}.award{font:500 90px/1.2 Oswald;margin-top:25px}#archive{top:1070px;text-align:left;font:400 28px/1.6 'IBM Plex Mono';color:#c2dbe2}#rejection{top:870px;background:#19151e;border:1px solid #c85a5a;padding:26px;font:400 39px/1.3 'IBM Plex Mono';color:#f2baba}#report{top:1080px;height:80px;font:500 49px/1.3 Oswald;color:#bfe2e8}.proof-badge{position:absolute;top:1750px;left:100px;font:400 19px/28px 'IBM Plex Mono';color:#9bb7c4;letter-spacing:2px}
'''
body='''<section id="stage" class="clip"><canvas data-layout-allow-overflow id="world" width="1080" height="1920" aria-label="Illustrative cinematic three-dimensional security architecture"></canvas><div id="editorial"><div id="eyebrow"><span>THE MISSING SIGNATURE</span><span id="shot-number"></span></div><h1 id="headline"></h1><div id="subtitle"></div></div><div id="admin" class="overlay"><div id="admin-label">upn → LOCAL USER</div><div id="admin-word"></div></div><div id="result" class="overlay"><div class="digit">1</div><div class="small">SELECT 1 → 1</div><div class="small amber">A QUERY RESULT. NOT A DATA DUMP.</div></div><div id="scale" class="overlay"><div class="value">17.3</div><div class="units">TRILLION · ESTIMATED ROWS</div><div class="qualifiers">POTENTIALLY REACHABLE\nNOT EXFILTRATED</div><div class="scale-note">Estimated scope, not a mass download</div></div><div id="claims" class="overlay"><div class="claim-head">HEADER / PAYLOAD / SIGNATURE</div><div class="claim-verdict">SIGNATURE: NOT VERIFIED</div></div><div id="dates" class="overlay"><div class="date-row">SEP 09 · ENDPOINT RESTRICTED</div><div class="date-row">SEP 17 · BOUNTY AWARDED</div><div class="award">$5,000</div></div><div id="archive" class="overlay">ARCHIVED CONFIGURATION<br>56 TABLE DEFINITIONS</div><div id="rejection" class="overlay">USER NOT FOUND</div><div id="report" class="overlay">REPORT SUBMITTED → MSRC</div><div id="attribution">DRAMATIZATION · SOURCE: FAAV'S PUBLIC DISCLOSURE</div><p id="caption"></p><div id="footer">A FAILURE TO VERIFY CRYPTOGRAPHIC PROOF</div></section>'''.replace('<br>','\n')
def html(duration,proof=False):
 attrs=' data-proof="true"' if proof else ''
 mapping=[]
 if proof:
  mapping=[{'at':0,'duration':4.3,'source':f['shots'][6]['start'],'sourceEnd':f['shots'][6]['end']},{'at':4.3,'duration':2,'source':f['shots'][7]['start'],'sourceEnd':f['shots'][7]['end']},{'at':6.3,'duration':3.7,'source':f['shots'][8]['start'],'sourceEnd':f['shots'][8]['end']}]
  attrs+=' data-source-map=\''+json.dumps(mapping)+'\''
 title='the-missing-signature-proof' if proof else f['id']
 return f'<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The Missing Signature</title><style>{style}</style></head><body><main id="film" data-composition-id="{title}" data-width="1080" data-height="1920" data-duration="{duration}"{attrs}>{body}'+('<div class="proof-badge">10-SECOND SHOT PROOF · S07 / S08 / S09</div>' if proof else '')+f'<audio id="mix" src="assets/audio/mix.wav" data-start="0" data-duration="{duration}" data-track-index="1"></audio></main><script src="assets/js/gsap.min.js"></script><script>window.__timelines=window.__timelines||{{}};window.__timelines["{title}"]=gsap.timeline({{paused:true}}).to({{clock:0}},{{clock:1,duration:{duration},ease:"none"}});</script><script type="module" src="dist/scene.js"></script></body></html>\n'
(p/'index.html').write_text(html(f['duration']))
proof=p/'proof';proof.mkdir(exist_ok=True);
if f.get('approval',{}).get('fullRender')!='approved':
 (proof/'index.html').write_text(html(10,True));shutil.copyfile(p/'hyperframes.json',proof/'hyperframes.json')
if f.get('approval',{}).get('fullRender')!='approved':shutil.copytree(p/'assets/fonts',proof/'assets/fonts',dirs_exist_ok=True)
print('HTML | approved full film generated; historical proof preserved' if f.get('approval',{}).get('fullRender')=='approved' else 'HTML | full film and proof generated')

for target in ([p] if f.get("approval",{}).get("fullRender")=="approved" else [p,p/"proof"]):
 (target/"assets/js").mkdir(exist_ok=True)
 shutil.copyfile("node_modules/gsap/dist/gsap.min.js",target/"assets/js/gsap.min.js")
 (target/"assets/js/GSAP-NOTICE.txt").write_text(Path("node_modules/gsap/dist/gsap.min.js").read_text().split("*/",1)[0]+"*/\n")
